param()

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$PatchName = "LearnLoot Udemy Scrape Robots-Compatible Recovery v2"
$AuthoritativeZip = "LearnLoot-develop(20260909-163343).zip"
$BackupSuffix = ".udemy-scrape-v1.bak"
$ScriptRoot = (Resolve-Path $PSScriptRoot).Path
$CurrentRoot = (Get-Location).Path

if (Test-Path -LiteralPath (Join-Path $ScriptRoot "backend\manage.py")) {
    $Root = $ScriptRoot
}
elseif (Test-Path -LiteralPath (Join-Path $CurrentRoot "backend\manage.py")) {
    $Root = $CurrentRoot
}
else {
    throw "Run this patch from the LearnLoot project root or place it in that root."
}

Write-Host $PatchName
Write-Host ("Root: " + $Root)
Write-Host ""

$ModifiedFiles = @(
    ".env.example"
    "backend\config\settings.py"
    "backend\discovery\udemy_catalog.py"
    "backend\discovery\providers\README.md"
    "backend\tests\test_admin_discovery.py"
    "backend\tests\test_phase5_discovery_operations.py"
    "backend\tests\test_scrapy_udemy_crawler.py"
    "backend\tests\test_udemy_free_provider.py"
)

$BackendPythonFiles = @(
    "backend\config\settings.py"
    "backend\discovery\udemy_catalog.py"
    "backend\tests\test_admin_discovery.py"
    "backend\tests\test_phase5_discovery_operations.py"
    "backend\tests\test_scrapy_udemy_crawler.py"
    "backend\tests\test_udemy_free_provider.py"
)

$ExpectedBaselineHashes = @{
    ".env.example" = "cba31db5e3009a548cdbb7d3cfb78c23fba6aced5cc89b4a839869c8559b3137"
    "backend\config\settings.py" = "3b212563695df2f1649f4e8e0ef9552917e1a7971a5cad71089e8d05d4d3ea62"
    "backend\discovery\udemy_catalog.py" = "e925e38cdaa30996236fcf85702807e838ad376f2bd33016a4bedc71d3c29653"
    "backend\discovery\providers\README.md" = "884ef899b9cd1465ef10222dda8e4d4278d62b0d2517574e63149232526f3779"
    "backend\tests\test_admin_discovery.py" = "2f99a54b2ce4440620ddf25d398ea39767c6ac780b0ebe257f27c904a3ecf6ee"
    "backend\tests\test_phase5_discovery_operations.py" = "09145c2d38e20e32d3929fc20706fc447a82c554537980152f8f5ade9278008f"
    "backend\tests\test_scrapy_udemy_crawler.py" = "20c4ea8b3a69a83a2e1d3b5ea4e747415a4603a5688e53d6650f6bd102ae6fed"
    "backend\tests\test_udemy_free_provider.py" = "15e16ba1d5d300473b15aa5104fbe878897560b16ef6e9667f11adf418496a1e"
}

$ExpectedGuardHashes = @{
    "backend\discovery\scrapy_app\settings.py" = "19f7b6dbca8bd68bcc7f3e555903cf17d1e30f24adc643709f15d1b02feb180c"
    "backend\discovery\scrapy_app\spiders\udemy_free.py" = "0584481e1371988b9b4b7fa687ab0f49c598df0966d873326354c719d848b5ad"
    "backend\discovery\registry.py" = "43b90b379c2df30b80838f6bacd5210e9b267ce4150a9fd4286057a24eb22fe3"
    "backend\cms\api.py" = "0f901c87de3a20250e063b3c801d8b3ef645f4aa1f52f233b85702b38c44e7d9"
    "backend\discovery\tasks.py" = "c37b26d7d8a22cd715112d8462a92ed28872f6cba181625a835002058aebd969"
    "backend\discovery\scrapy_app\runner.py" = "23c2065745d82712b4faef13f0dcae094407a3102f7667e53d5c134a40a74a9a"
    "backend\discovery\providers\udemy_free.py" = "d3506619e546e053864781ce3109460c971d0221a36c26cac92d0520f2f45d6d"
    "backend\requirements.txt" = "a5ff2a0573eeee4b3633d964042203ab53e0978b288dd6a2ee8a79a7b8aaa9b2"
    "backend\manage.py" = "9e055a3ca49f173675232d3f61d1feb89f1350708fb25a002f6d3edefeec6db4"
}

$ExpectedTargetHashes = @{
    ".env.example" = "4b1dddd1b94fe895b7112dbb02c62cd393fc005212238230f83c0dd290505783"
    "backend\config\settings.py" = "e231dc3035209053a26369f51c9878aa0020b229b0aa8d92e709bdba866c063a"
    "backend\discovery\udemy_catalog.py" = "c1eb6d3eb98d51ebc7715657d8341bf69a09e04937590d4cdd18e22adf2410a9"
    "backend\discovery\providers\README.md" = "96f3d4329f7f94cf4b316caecf7ef9030dc47a532c7601ed03aba106d518041f"
    "backend\tests\test_admin_discovery.py" = "f9cddb67ac9a564e34b4db3ba5a5047e6e072ff574621b6cb7e260a0e0988c72"
    "backend\tests\test_phase5_discovery_operations.py" = "7e091ca4493a4c86ef79694519275010140695ef1899b03e0aa1199d6b8c4f84"
    "backend\tests\test_scrapy_udemy_crawler.py" = "bae770b2fee0585076f4ef38a2987e45e3cf2751437b194f3a365f30bf79b1e9"
    "backend\tests\test_udemy_free_provider.py" = "35f8c3177b2d9e0b64c1ad723e86f051bef1aaf9e83217c31cf861e33335caac"
}

$PayloadBase64 = @{
    ".env.example" = ""
    "backend\config\settings.py" = ""
    "backend\discovery\udemy_catalog.py" = ""
    "backend\discovery\providers\README.md" = ""
    "backend\tests\test_admin_discovery.py" = ""
    "backend\tests\test_phase5_discovery_operations.py" = ""
    "backend\tests\test_scrapy_udemy_crawler.py" = ""
    "backend\tests\test_udemy_free_provider.py" = ""
}

$Python = Join-Path $Root ".venv\Scripts\python.exe"
$Backups = New-Object 'System.Collections.Generic.List[string]'
$WriteStarted = $false

function Get-ProjectPath {
    param([string]$RelativePath)
    return Join-Path $Root ($RelativePath -replace '/', [IO.Path]::DirectorySeparatorChar)
}

function Get-NormalizedText {
    param([string]$Path)
    $text = [System.IO.File]::ReadAllText($Path)
    return (($text -replace "`r`n", "`n") -replace "`r", "`n")
}

function Get-NormalizedSha256 {
    param([string]$Path)
    $bytes = [Text.Encoding]::UTF8.GetBytes((Get-NormalizedText $Path))
    $sha = [Security.Cryptography.SHA256]::Create()
    try { $hash = $sha.ComputeHash($bytes) } finally { $sha.Dispose() }
    return ([BitConverter]::ToString($hash)).Replace("-", "").ToLowerInvariant()
}

function Fail-Preflight {
    param([string]$Message)
    throw ("Preflight failed: " + $Message + " No source files were changed.")
}

function Assert-Hash {
    param([string]$RelativePath, [string]$Expected, [string]$Label)
    $path = Get-ProjectPath $RelativePath
    if (-not (Test-Path -LiteralPath $path)) {
        Fail-Preflight ("required " + $Label + " file is missing: " + $RelativePath)
    }
    $actual = Get-NormalizedSha256 $path
    if ($actual -ne $Expected) {
        Fail-Preflight ($Label + " hash mismatch in " + $RelativePath + ". Expected " + $Expected + ", found " + $actual + ".")
    }
}

function Invoke-ExternalGate {
    param([string]$Label, [scriptblock]$Action)
    Write-Host ""
    Write-Host ("==> " + $Label)
    & $Action
    if ($LASTEXITCODE -ne 0) {
        throw ("Gate failed: " + $Label + " (exit code " + $LASTEXITCODE + ")")
    }
}

function Prepare-Backup {
    param([string]$RelativePath)
    $path = Get-ProjectPath $RelativePath
    $backup = $path + $BackupSuffix
    if (Test-Path -LiteralPath $backup) {
        $backupHash = Get-NormalizedSha256 $backup
        if ($backupHash -ne $ExpectedBaselineHashes[$RelativePath]) {
            Fail-Preflight ("existing patch backup does not match the authoritative baseline: " + $RelativePath + $BackupSuffix)
        }
        Write-Host ("Verified retained patch backup: " + $RelativePath + $BackupSuffix)
    }
    else {
        Copy-Item -LiteralPath $path -Destination $backup
    }
    $Backups.Add($backup)
}

function Write-Payload {
    param([string]$RelativePath)
    $path = Get-ProjectPath $RelativePath
    $bytes = [Convert]::FromBase64String($PayloadBase64[$RelativePath])
    [IO.File]::WriteAllBytes($path, $bytes)
}

function Restore-Source {
    Write-Host "Restoring modified source files from patch backups..."
    foreach ($backup in $Backups) {
        $original = $backup.Substring(0, $backup.Length - $BackupSuffix.Length)
        Copy-Item -LiteralPath $backup -Destination $original -Force
    }
    Write-Host "Source restoration completed. Patch backups were retained for verification."
}

function Remove-PatchBackups {
    foreach ($backup in $Backups) {
        if (Test-Path -LiteralPath $backup) { Remove-Item -LiteralPath $backup -Force }
    }
}

try {
    Write-Host ("Preflight: validating exact authoritative " + $AuthoritativeZip + " baseline...")

    foreach ($entry in $ExpectedBaselineHashes.GetEnumerator()) {
        Assert-Hash $entry.Key $entry.Value "authoritative baseline"
    }
    foreach ($entry in $ExpectedGuardHashes.GetEnumerator()) {
        Assert-Hash $entry.Key $entry.Value "scraper-flow guard"
    }

    if (-not (Test-Path -LiteralPath $Python)) {
        Fail-Preflight "project virtualenv Python is missing at .venv\Scripts\python.exe"
    }

    foreach ($relative in $ModifiedFiles) {
        $backup = (Get-ProjectPath $relative) + $BackupSuffix
        if (Test-Path -LiteralPath $backup) {
            $backupHash = Get-NormalizedSha256 $backup
            if ($backupHash -ne $ExpectedBaselineHashes[$relative]) {
                Fail-Preflight ("existing patch backup does not match the authoritative baseline: " + $relative + $BackupSuffix)
            }
            Write-Host ("Verified retained patch backup: " + $relative + $BackupSuffix)
        }
    }

    $scrapySettings = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\settings.py")
    if ($scrapySettings -notmatch 'ROBOTSTXT_OBEY\s*=\s*True') {
        Fail-Preflight "Scrapy robots compliance is not enabled."
    }

    if (Test-Path -LiteralPath (Join-Path $Root ".git")) {
        Write-Host "Git working tree before patch:"
        $env:GIT_PAGER = "cat"
        $env:PAGER = "cat"
        & git -C $Root --no-pager status --short
        if ($LASTEXITCODE -ne 0) { Fail-Preflight "git status failed" }
    }

    Invoke-ExternalGate "Preflight project virtualenv Django import" {
        & $Python -c "import django; print('DJANGO_VERSION=' + django.get_version())"
    }
    Invoke-ExternalGate "Preflight Django system check" {
        & $Python (Join-Path $Root "backend\manage.py") check
    }
    Invoke-ExternalGate "Preflight migration application check" {
        & $Python (Join-Path $Root "backend\manage.py") migrate --check
    }
    Invoke-ExternalGate "Preflight migration drift check" {
        & $Python (Join-Path $Root "backend\manage.py") makemigrations --check --dry-run
    }

    Write-Host ""
    Write-Host "Preflight PASS. Creating patch-owned backups..."
    foreach ($relative in $ModifiedFiles) { Prepare-Backup $relative }
    $WriteStarted = $true

    foreach ($relative in $ModifiedFiles) { Write-Payload $relative }

    foreach ($entry in $ExpectedTargetHashes.GetEnumerator()) {
        $path = Get-ProjectPath $entry.Key
        $actual = Get-NormalizedSha256 $path
        if ($actual -ne $entry.Value) {
            throw ("Target hash mismatch after write in " + $entry.Key + ". Expected " + $entry.Value + ", found " + $actual)
        }
    }
    Write-Host "Exact UTF-8 payload verification: PASS"

    $catalog = Get-NormalizedText (Get-ProjectPath "backend\discovery\udemy_catalog.py")
    $settingsText = Get-NormalizedText (Get-ProjectPath "backend\config\settings.py")
    $spider = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\spiders\udemy_free.py")
    $scrapySettings = Get-NormalizedText (Get-ProjectPath "backend\discovery\scrapy_app\settings.py")
    if ($catalog -notmatch 'UDEMY_DEFAULT_SEARCH_URL\s*=\s*"https://www\.udemy\.com/courses/free/"') {
        throw "Semantic guard failed: live Udemy source is not the public /courses/free/ catalog."
    }
    if ($catalog -notmatch '_LEGACY_SEARCH_PATH\s*=\s*"/courses/search/"') {
        throw "Semantic guard failed: legacy free-search compatibility is missing."
    }
    if ($catalog -notmatch 'return UDEMY_DEFAULT_SEARCH_URL') {
        throw "Semantic guard failed: source normalization is not routing to the free catalog."
    }
    if ($catalog -notmatch 'Use https://www\.udemy\.com/courses/free/ for live Udemy crawling') {
        throw "Semantic guard failed: direct faceted search crawling is not rejected."
    }
    if ($settingsText -notmatch 'default="https://www\.udemy\.com/courses/free/"') {
        throw "Semantic guard failed: Django default discovery source was not updated."
    }
    if ($spider -notmatch 'query\["p"\]\s*=\s*str\(page_number\)') {
        throw "Semantic guard failed: scraper pagination no longer uses the bounded p facet."
    }
    if ($scrapySettings -notmatch 'ROBOTSTXT_OBEY\s*=\s*True') {
        throw "Semantic guard failed: robots compliance was disabled."
    }
    Write-Host "Robots-compatible Udemy source semantic guards: PASS"

    $adminDiscoveryTest = Get-NormalizedText (Get-ProjectPath "backend\tests\test_admin_discovery.py")
    if ($adminDiscoveryTest -notmatch 'search_filters"\]\["label"\]\s*==\s*"Udemy free courses"') {
        throw "Semantic guard failed: admin discovery regression expectation was not updated for the free catalog."
    }
    Write-Host "Udemy free-catalog admin regression guard: PASS"

    Invoke-ExternalGate "Python syntax verification" {
        $paths = @($BackendPythonFiles | ForEach-Object { Get-ProjectPath $_ })
        & $Python -c "import ast,pathlib,sys; [ast.parse(pathlib.Path(p).read_text(encoding='utf-8'), filename=p) for p in sys.argv[1:]]" @paths
    }
    Invoke-ExternalGate "Django system check" {
        & $Python (Join-Path $Root "backend\manage.py") check
    }
    Invoke-ExternalGate "Migration application check" {
        & $Python (Join-Path $Root "backend\manage.py") migrate --check
    }
    Invoke-ExternalGate "Migration drift check" {
        & $Python (Join-Path $Root "backend\manage.py") makemigrations --check --dry-run
    }

    $FocusedPytestBaseTemp = Join-Path $Root (".pytest-learnloot-udemy-focus-" + [Guid]::NewGuid().ToString("N"))
    $FullPytestBaseTemp = Join-Path $Root (".pytest-learnloot-udemy-full-" + [Guid]::NewGuid().ToString("N"))
    Push-Location (Join-Path $Root "backend")
    try {
        Invoke-ExternalGate "Focused Udemy discovery/scraper tests" {
            & $Python -m pytest `
                ("--basetemp=" + $FocusedPytestBaseTemp) `
                tests\test_admin_discovery.py `
                tests\test_phase5_discovery_operations.py `
                tests\test_scrapy_udemy_crawler.py `
                tests\test_udemy_free_provider.py
        }
        Invoke-ExternalGate "Full backend regression suite" {
            & $Python -m pytest ("--basetemp=" + $FullPytestBaseTemp)
        }
    }
    finally {
        Pop-Location
        foreach ($testTemp in @($FocusedPytestBaseTemp, $FullPytestBaseTemp)) {
            if (Test-Path -LiteralPath $testTemp) {
                Remove-Item -LiteralPath $testTemp -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    if (Test-Path -LiteralPath (Join-Path $Root ".git")) {
        Invoke-ExternalGate "Git whitespace check (pager disabled)" {
            $env:GIT_PAGER = "cat"
            $env:PAGER = "cat"
            & git -C $Root --no-pager diff --check
        }
    }

    Remove-PatchBackups

    Write-Host ""
    Write-Host "UDEMY_SCRAPE_FIX_PATCH=PASS"
    Write-Host "UDEMY_SCRAPE_FIX=PASS"
    Write-Host "Udemy discovery now normalizes legacy faceted free-search configuration to https://www.udemy.com/courses/free/."
    Write-Host "The live spider still obeys robots.txt and uses only the ?p= pagination facet."
    Write-Host "No database migration was required."
    Write-Host ""
    Write-Host "Optional read-only live verification:"
    Write-Host ".venv\Scripts\python.exe backend\manage.py smoke_udemy_free --acknowledge-access-terms --limit 5"
}
catch {
    $message = $_.Exception.Message
    Write-Host ""
    if ($WriteStarted) {
        Write-Host ("UDEMY_SCRAPE_FIX_PATCH=FAIL: " + $message)
        Restore-Source
    }
    else {
        Write-Host ("UDEMY_SCRAPE_FIX_PATCH=FAIL_PREFLIGHT: " + $message)
    }
    exit 1
}
